Definition cnt_tab (m : mem) (tab : Z) (vals : list Z) : Prop :=
  u32arr asegs m tab (map (Z_to_bv 64) vals) /\ Z.of_nat (length vals) = 256 /\ Forall (fun v => 0 <= v <= 8) vals.

